        showToast(this.classList.contains('on') ? '\u{1F916} \u81EA\u52A8\u542F\u52A8\u5DF2\u5F00\u542F' : '\u{1F512} \u81EA\u52A8\u542F\u52A8\u5DF2\u5173\u95ED', this.classList.contains('on') ? '#00ba7c' : '#f91880');
        updateMasterBtn();
