                localStorage.setItem('sg_state', JSON.stringify(st));
                try { setChatPhase('inbox'); } catch (ePh) {}
                try { setRunMode('inbox'); } catch (eMode) {}
                try { sessionStorage.setItem('dan_auto_run', 'true'); } catch (eAuto) {}
                // 启动守箱脉冲：立即触发第一次，之后按间隔循环
                try {
                    var pulseSt = loadInboxState();
                    pulseSt.running = true;
                    pulseSt.busy = false;
                    pulseSt.intervalMs = getInboxPulseIntervalMs();
                    pulseSt.nextPulseAt = Date.now();
                    pulseSt.startedAt = pulseSt.startedAt || Date.now();
                    saveInboxState(pulseSt);
                    try { localStorage.setItem('sg_inbox_autostart', '1'); } catch (eAutoFlag) {}
                    out.pulse = { running: true, intervalMs: pulseSt.intervalMs, nextPulseAt: pulseSt.nextPulseAt };
                } catch (ePulseStart) {}
                try { ensureChatMainEngine(); } catch (eEngineStart) {}
                out.phase = 'inbox';
